/**
 * Web only: registers the offline service worker generated by scripts/build-sw.ts.
 * Production builds only. When a new build takes over an already running page, the page reloads
 * once so the new build shows up right away. This is safe: the service worker keeps the previous
 * build's files too, so the old page keeps working until it reloads.
 */
export function registerServiceWorker(): void {
  if (typeof navigator === 'undefined' || !('serviceWorker' in navigator)) return;
  if (process.env.NODE_ENV !== 'production') return;
  const base = process.env.EXPO_BASE_URL ?? '';
  const hadController = navigator.serviceWorker.controller !== null;
  let reloaded = false;
  navigator.serviceWorker.addEventListener('controllerchange', () => {
    // The very first install also takes control; only reload for real updates.
    if (!hadController || reloaded) return;
    reloaded = true;
    window.location.reload();
  });
  const register = () => {
    navigator.serviceWorker.register(`${base}/sw.js`, { scope: `${base}/` }).catch((error) => {
      console.warn('Service worker registration failed', error);
    });
  };
  if (document.readyState === 'complete') register();
  else window.addEventListener('load', register, { once: true });
}
